package org.pacos.plugin.kafka.config;
import com.zaxxer.hikari.HikariDataSource; import jakarta.persistence.EntityManagerFactory; import org.springframework.beans.factory.annotation.*; import org.springframework.context.annotation.*; import org.springframework.core.env.Environment; import org.springframework.data.jpa.repository.config.EnableJpaRepositories; import org.springframework.orm.jpa.*; import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter; import org.springframework.transaction.*; import org.springframework.transaction.annotation.EnableTransactionManagement; import javax.sql.DataSource; import java.util.*;
@Configuration @EnableTransactionManagement @DependsOn("kafkaFlyWayMigration") @EnableJpaRepositories(basePackages="org.pacos.plugin.kafka.backend",entityManagerFactoryRef="kafkaEntityManagerFactory",transactionManagerRef="kafkaTransactionManager") @PropertySource("classpath:kafka-module.properties")
public class KafkaDataSourceConfig { private final Environment env; public KafkaDataSourceConfig(Environment env){this.env=env;}
 @Bean("kafkaDataSource") DataSource kafkaDataSource(){HikariDataSource d=new HikariDataSource();d.setDriverClassName(Objects.requireNonNull(env.getProperty("kafka.datasource.driverClassName")));d.setJdbcUrl(env.getProperty("kafka.datasource.url"));d.setUsername(env.getProperty("kafka.datasource.username"));d.setPassword(env.getProperty("kafka.datasource.password"));d.setMaximumPoolSize(10);d.setMinimumIdle(2);d.setConnectionTimeout(30000);return d;}
 @Bean LocalContainerEntityManagerFactoryBean kafkaEntityManagerFactory(@Qualifier("kafkaDataSource") DataSource ds){HibernateJpaVendorAdapter a=new HibernateJpaVendorAdapter();a.setGenerateDdl(false);LocalContainerEntityManagerFactoryBean e=new LocalContainerEntityManagerFactoryBean();e.setDataSource(ds);e.setPackagesToScan("org.pacos.plugin.kafka.backend");e.setJpaVendorAdapter(a);e.setPersistenceUnitName("kafkaModule");Map<String,Object> p=new HashMap<>();p.put("hibernate.hbm2ddl.auto","none");p.put("hibernate.connection.provider_disables_autocommit","true");e.setJpaPropertyMap(p);return e;}
 @Bean PlatformTransactionManager kafkaTransactionManager(@Qualifier("kafkaEntityManagerFactory") EntityManagerFactory emf){return new JpaTransactionManager(emf);}
}